// Obtener configuración de WordPress
const config = $input.first().json;
const weekSchedule = config.data?.weekSchedule || {};
const holidays = config.data?.holidays || [];

// Generar los próximos días disponibles con validación
const now = new Date();
const days = [];
let checkDate = now;

const dayNames = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
const diasES = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];

while (days.length < 3 && checkDate < new Date(now.getTime() + 14 * 24 * 60 * 60 * 1000)) {
  checkDate = new Date(checkDate.getTime() + 24 * 60 * 60 * 1000);
  const dayOfWeek = checkDate.getDay();
  const dayName = dayNames[dayOfWeek];
  const dateKey = checkDate.toISOString().split('T')[0];

  // Verificar si el día está habilitado
  const dayConfig = weekSchedule[dayName] || { enabled: false };
  if (!dayConfig.enabled) continue;

  // Verificar si es feriado
  if (holidays.includes(dateKey)) continue;

  // Agregar día disponible
  const [year, month, day] = dateKey.split('-');
  days.push({
    date: dateKey,
    display: `${diasES[dayOfWeek]} ${day}/${month}`,
    btnId: `day_${dateKey}`
  });
}

return {
  json: {
    ...$('Normalize Input').first().json,
    availableDays: days
  }
};

