// Obtener eventos del día y configuración
const events = $input.all().filter(i => i.json.start);
const config = $input.all().filter(i => i.json.data)[0]?.json || {};
const inputData = $('Normalize Input').first().json;

const selectedDay = inputData.selectedDay;
const weekSchedule = config.data?.weekSchedule || {};

// Obtener día de la semana
const date = new Date(selectedDay + 'T12:00:00');
const dayNames = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
const dayName = dayNames[date.getDay()];
const dayConfig = weekSchedule[dayName] || { enabled: true, start: '09:00', end: '18:00' };

if (!dayConfig.enabled) {
  return {
    json: {
      ...inputData,
      hasAvailability: false,
      message: 'Lo siento, ese día no hay atención disponible. ¿Te gustaría elegir otro día?'
    }
  };
}

// Obtener horarios ocupados
const busySlots = [];
for (const event of events) {
  if (event.json.start && event.json.start.dateTime) {
    const startTime = new Date(event.json.start.dateTime);
    busySlots.push(startTime.getHours() + ':00');
  }
}

// Generar horarios disponibles según configuración
const [startHour] = dayConfig.start.split(':').map(Number);
const [endHour] = dayConfig.end.split(':').map(Number);

const allSlots = [];
for (let hour = startHour; hour < endHour; hour++) {
  allSlots.push(hour + ':00');
}

const availableSlots = allSlots.filter(slot => !busySlots.includes(slot));

if (availableSlots.length === 0) {
  return {
    json: {
      ...inputData,
      hasAvailability: false,
      message: 'Lo siento, no hay horarios disponibles para ese día. ¿Te gustaría elegir otro día?'
    }
  };
}

// Tomar los primeros 3 disponibles
const slotsToShow = availableSlots.slice(0, 3);
const formattedSlots = slotsToShow.map(slot => ({
  time: slot,
  display: slot + ' hrs',
  btnId: `time_${selectedDay}_${slot.replace(':', '')}`
}));

return {
  json: {
    ...inputData,
    hasAvailability: true,
    availableSlots: formattedSlots
  }
};

